import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph RGW Refactoring Meeting - 2/18/2026","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting - 2/18/2026","date":"2026-05-13T00:00:00.000Z","updated":"2026-05-14T00:00:00.000Z","tags":["Ceph RGW","RADOS","OSD","可观测性","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_-_2_18_2026.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_-_2_18_2026.md","lastUpdated":1780459816000}'),i={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_-_2_18_2026.md"};function d(n,e,l,s,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 RGW Refactoring Meeting 于 2026 年 2 月 18 日举行，主要讨论了两个议题：一是 RGW 中 objector（对象追踪器）introspection 功能当前存在的问题及修复方案；二是 Swift <code>X-Delete-After</code> header 的一个已知 bug 及对应 PR 的审查进展。</p><h2 id="议题一-rgw-objector-请求追踪问题-gruno-主导" tabindex="-1">议题一：RGW objector 请求追踪问题（Gruno 主导） <a class="header-anchor" href="#议题一-rgw-objector-请求追踪问题-gruno-主导" aria-label="Permalink to &quot;议题一：RGW objector 请求追踪问题（Gruno 主导）&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>Ceph 提供了一个类似 OSD <code>dump ops</code> 的功能，可以通过 admin socket 查询 RGW gateway 当前正在向 RADOS 发送的所有请求（即 objector requests）。这对于生产环境排查 RADOS hang、定位阻塞的 PG 或 OSD 非常有价值。</p><p>然而，该功能在 RGW 上实际上是<strong>不可用的</strong>，而在 RBD、CephFS 等其他客户端上可以正常工作。</p><h3 id="根本原因" tabindex="-1">根本原因 <a class="header-anchor" href="#根本原因" aria-label="Permalink to &quot;根本原因&quot;">​</a></h3><p>RGW 当前初始化了<strong>多个 librados 实例</strong>：</p><ul><li>一个用于 config store</li><li>一个用于实际的 S3 数据请求（最关键的一个）</li><li>一个用于 NeoRADOS（异步接口）</li><li>一个用于 realm watch（近期已有 PR 修复其导致的内存泄漏）</li></ul><p>objector 的注册机制存在缺陷：第一个 librados 实例创建时会注册 admin socket hook，后续实例创建时由于 hook 已存在，会<strong>静默忽略</strong>，不再注册。因此，通过 admin socket 查询到的 objector 数据实际上只来自 config store 的 librados 实例，而非 S3 请求路径，导致该功能对 RGW 实际上形同虚设。</p><h3 id="讨论方案" tabindex="-1">讨论方案 <a class="header-anchor" href="#讨论方案" aria-label="Permalink to &quot;讨论方案&quot;">​</a></h3><p><strong>方案一：合并所有 librados 实例为单一实例</strong></p><p>优点：架构更清晰，符合 RBD/CephFS 的做法。 缺点：改动量大，config store 可能需要独立后端，NeoRADOS 与 legacy RADOS 的合并也较为复杂，难以验证正确性。</p><p><strong>方案二：让 objector 支持多个 librados 实例</strong></p><p>即修改 objector，使其能够聚合多个实例的 ops，以 JSON array 或合并方式返回。 缺点：会改变现有 admin socket 命令的输出格式，可能影响依赖该格式的其他组件。</p><p><strong>方案三（最终共识）：为每个 librados 实例设置不同的 socket 名称</strong></p><p>在 librados 的 <code>rados.init</code> 和 <code>rados.connect</code> 之间，新增一个 API（如 <code>set_objector_admin_socket_name</code>），允许应用层在初始化时为每个 librados 实例指定唯一的 socket 名称。若不设置，则保持默认行为不变，对其他客户端（RBD、CephFS）无影响。</p><p>Gruno 已有一个 draft PR 演示了该方案的实现，测试验证可行。admin socket 的 <code>help</code> 命令可以发现所有已注册的 objector 命令，用户可通过 discovery 找到对应的命令名称。</p><p><strong>后续行动：</strong></p><ul><li>Gruno 将提交正式 PR，为 librados 添加 <code>set_objector_admin_socket_name</code> API</li><li>在 RGW 侧为各 librados 实例（NeoRADOS、legacy RADOS 等）分别设置不同名称</li></ul><h3 id="子议题-为-objector-dump-添加-transaction-id-关联" tabindex="-1">子议题：为 objector dump 添加 Transaction ID 关联 <a class="header-anchor" href="#子议题-为-objector-dump-添加-transaction-id-关联" aria-label="Permalink to &quot;子议题：为 objector dump 添加 Transaction ID 关联&quot;">​</a></h3><p><strong>问题描述</strong></p><p>当前 objector dump 输出的是 RADOS 层面的对象 ID，无法直接关联到 S3 bucket、S3 object 或 S3 user。同时，RGW 的请求日志（access log、ops log）只在请求<strong>完成后</strong>才写入，当后端 RADOS 阻塞时，无法通过日志追溯正在进行中的请求。</p><p><strong>提案</strong></p><p>在 objector 的 op 结构体中新增一个字段（caller ID / transaction ID），允许应用层在提交 RADOS op 时附带一个字符串标识（如 RGW 的 <code>trans_id</code>），从而将 RADOS 层的 op 与前端 S3 请求完整关联起来。</p><p><strong>讨论要点</strong></p><ul><li>Casey 对直接向 librados AIO 接口添加随机参数持保留意见，认为 librados 应保持稳定、通用的 API 设计。</li><li>有人提出复用现有的 Jaeger tracing 结构，但该结构仅在启用分布式 tracing 时生效，存在性能开销，不适合作为常规 introspection 手段。</li><li>最终共识：在 <strong>op 结构体</strong>上新增一个紧凑字段（字符串类型），通过新增一个 object operation 的 setter 函数暴露给应用层，而非修改 AIO 函数签名。RGW 侧在构建 RADOS op 时，从 RGW op 的 <code>trans_id</code> 中取值并设置，非 RGW 上下文的请求则不设置。</li><li>明确不应使用 thread local storage（存在协程调度导致值错误的问题）。</li><li>不应复用现有的 <code>T</code>（递增计数器）字段，以免破坏现有语义。</li></ul><p><strong>后续行动：</strong></p><ul><li>Gruno 将为该功能单独创建一个 tracker，并在后续 PR 中讨论具体实现细节</li><li>两个 PR（socket 命名 + caller ID）保持独立，分开提交</li></ul><h2 id="议题二-swift-x-delete-after-重复设置-bug-david-主导" tabindex="-1">议题二：Swift X-Delete-After 重复设置 Bug（David 主导） <a class="header-anchor" href="#议题二-swift-x-delete-after-重复设置-bug-david-主导" aria-label="Permalink to &quot;议题二：Swift X-Delete-After 重复设置 Bug（David 主导）&quot;">​</a></h2><h3 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h3><p>Swift 协议支持 <code>X-Delete-After</code> header，允许用户指定对象在若干分钟后自动删除。当前存在一个 bug：<strong>若对同一对象两次设置该 header，只有第一次的值生效</strong>，后续设置被忽略。</p><p>该 bug 已有对应 PR 开放约一年，实现方式是在 <code>cls_time_index</code> 的 insert 函数中，插入前先检查并删除已有的旧 key。</p><h3 id="讨论要点" tabindex="-1">讨论要点 <a class="header-anchor" href="#讨论要点" aria-label="Permalink to &quot;讨论要点&quot;">​</a></h3><ul><li><code>cls_time_index</code> 目前主要用于对象过期（object expiration）功能，S3 的 restore object（临时副本到期删除）也使用了该机制。</li><li>性能影响：每次 insert 多一次查找，但由于使用场景有限，性能代价可接受，正确性更重要。</li><li>测试覆盖：<code>source/test</code> 目录下有大量 CLS 客户端 API 的测试用例，但目前<strong>缺少针对 <code>cls_time_index</code> 的单元测试</strong>。</li></ul><h3 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h3><ul><li>Casey 将在该 PR 中补充测试指导意见（action item）</li><li>鼓励 PR 作者补充针对 overwrite 场景的单元测试</li><li>Swift 相关功能在社区关注度较低，需要更多人参与审查</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>负责人</th><th>状态</th></tr></thead><tbody><tr><td>提交 librados socket 命名 PR</td><td>Gruno</td><td>待提交</td></tr><tr><td>创建 caller ID / transaction ID tracker</td><td>Gruno</td><td>待创建</td></tr><tr><td>在 cls_time_index PR 中补充测试指导</td><td>Casey</td><td>待完成</td></tr><tr><td>Swift X-Delete-After bug PR审查</td><td>团队</td><td>进行中</td></tr></tbody></table>',39)])])}const b=t(i,[["render",d]]);export{g as __pageData,b as default};
